import { useState } from 'react';
import { Icon } from '@iconify/react';

const BOOKS = [
  { title: "Kitaab at-Tawheed", author: "Muhammad ibn Abd al-Wahhab", level: "Beginner", category: "Aqeedah", desc: "Foundational book on Islamic monotheism" },
  { title: "Riyad as-Salihin", author: "Imam al-Nawawi", level: "Intermediate", category: "Hadith", desc: "Gardens of the Righteous — comprehensive Hadith compilation" },
  { title: "Ihya Ulum al-Din", author: "Imam al-Ghazali", level: "Advanced", category: "Tazkiyah", desc: "Revival of the Religious Sciences" },
  { title: "Ar-Raheeq al-Makhtum", author: "Saifur Rahman al-Mubarakpuri", level: "Beginner", category: "Seerah", desc: "The Sealed Nectar — famous biography of Prophet ﷺ" },
  { title: "Tafsir Ibn Kathir", author: "Ibn Kathir", level: "Advanced", category: "Tafsir", desc: "Most widely studied Quran commentary" },
  { title: "Don't Be Sad", author: "Aid al-Qarni", level: "Contemporary", category: "Self-Help", desc: "Guide to peace of mind through Islamic teachings" },
  { title: "Thalaathat al-Usool", author: "Muhammad ibn Abd al-Wahhab", level: "Beginner", category: "Aqeedah", desc: "The Three Fundamental Principles" },
  { title: "Madarij as-Salikin", author: "Ibn al-Qayyim", level: "Advanced", category: "Tazkiyah", desc: "Ranks of the Divine Seekers" },
  { title: "Al-Aqeedah al-Waasitiyyah", author: "Ibn Taymiyyah", level: "Intermediate", category: "Aqeedah", desc: "Creed of the Middle Path" },
  { title: "Buloogh al-Maram", author: "Ibn Hajar al-Asqalani", level: "Intermediate", category: "Hadith", desc: "Collection of Hadith on Islamic rulings" },
  { title: "Zaad al-Ma'ad", author: "Ibn al-Qayyim", level: "Advanced", category: "Seerah", desc: "Provisions for the Hereafter from the guidance of the Prophet" },
  { title: "Reclaim Your Heart", author: "Yasmin Mogahed", level: "Contemporary", category: "Spirituality", desc: "Spiritual reflections on detachment and purpose" },
];

export default function Books() {
  const [search, setSearch] = useState('');
  const [level, setLevel] = useState('All');
  const [category, setCategory] = useState('All');

  const filtered = BOOKS.filter(book => {
    const matchesSearch = book.title.toLowerCase().includes(search.toLowerCase()) ||
                         book.author.toLowerCase().includes(search.toLowerCase()) ||
                         book.desc.toLowerCase().includes(search.toLowerCase());
    const matchesLevel = level === 'All' || book.level === level;
    const matchesCategory = category === 'All' || book.category === category;
    return matchesSearch && matchesLevel && matchesCategory;
  });

  const levels = ['All', 'Beginner', 'Intermediate', 'Advanced', 'Contemporary'];
  const categories = ['All', ...new Set(BOOKS.map(b => b.category))];

  const getLevelColor = (level) => {
    const colors = {
      'Beginner': 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300',
      'Intermediate': 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300',
      'Advanced': 'bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300',
      'Contemporary': 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300',
    };
    return colors[level] || 'bg-gray-100 text-gray-700';
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="text-center mb-12 p-12 bg-gradient-to-br from-green-50 to-yellow-50 dark:from-green-900 dark:to-yellow-900 rounded-2xl">
        <h1 className="arabic-text text-5xl font-bold mb-4 text-green-700 dark:text-green-400">
          اقْرَأْ بِاسْمِ رَبِّكَ
        </h1>
        <h2 className="text-4xl font-bold mb-4 text-green-700 dark:text-green-400">Islamic Books Library</h2>
        <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
          "Read in the name of your Lord who created." — Quran 96:1
        </p>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4 mb-8">
        <div className="flex-1 relative">
          <Icon icon="ph:magnifying-glass-duotone" className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search by title, author, or description..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
          />
        </div>
        <select
          value={level}
          onChange={(e) => setLevel(e.target.value)}
          className="px-4 py-3 rounded-xl border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
        >
          {levels.map(l => (
            <option key={l} value={l}>{l === 'All' ? 'All Levels' : l}</option>
          ))}
        </select>
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value)}
          className="px-4 py-3 rounded-xl border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
        >
          {categories.map(c => (
            <option key={c} value={c}>{c === 'All' ? 'All Categories' : c}</option>
          ))}
        </select>
      </div>

      {/* Results count */}
      <p className="text-gray-500 dark:text-gray-400 mb-6">
        Showing {filtered.length} of {BOOKS.length} books
      </p>

      {/* Books Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(book => (
          <div key={book.title} className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg hover:shadow-xl transition-all hover:-translate-y-1 overflow-hidden">
            <div className="p-6">
              <div className="flex justify-between items-start mb-3">
                <span className={`inline-block px-3 py-1 rounded-full text-xs font-semibold ${getLevelColor(book.level)}`}>
                  {book.level}
                </span>
                <Icon icon="ph:bookmark-duotone" className="w-5 h-5 text-gray-400 hover:text-green-500 cursor-pointer" />
              </div>
              <h3 className="font-bold text-lg mb-2 text-gray-900 dark:text-white">{book.title}</h3>
              <p className="text-gray-500 dark:text-gray-400 text-sm mb-1">by {book.author}</p>
              <p className="text-gray-600 dark:text-gray-400 text-sm mb-4">{book.desc}</p>
              <div className="flex items-center justify-between">
                <span className="inline-block px-2 py-1 rounded text-xs bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400">
                  {book.category}
                </span>
                <button className="text-green-600 hover:text-green-700 dark:text-green-400 dark:hover:text-green-300 text-sm font-medium inline-flex items-center gap-1">
                  View Details
                  <Icon icon="ph:arrow-right-duotone" className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="text-center py-12">
          <Icon icon="ph:books-duotone" className="w-16 h-16 mx-auto text-gray-400 mb-4" />
          <p className="text-gray-500 dark:text-gray-400 text-lg">No books found matching your criteria</p>
        </div>
      )}
    </div>
  );
}
